"""The model JSON files are generated by tools/build_models.py: keep them in sync."""
import importlib.util
import json

from conftest import ROOT


def load_builder():
    spec = importlib.util.spec_from_file_location("build_models", ROOT / "tools" / "build_models.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_models_up_to_date():
    b = load_builder()
    for mid, model in b.models().items():
        path = ROOT / ".fz" / "models" / f"{mid}.json"
        assert path.read_text() == b.render(model), f"{path.name} is stale: run python tools/build_models.py"


def test_models_valid():
    for path in (ROOT / ".fz" / "models").glob("*.json"):
        model = json.loads(path.read_text())
        assert model["id"] == path.stem
        assert model["varprefix"] == "&" and model["formulaprefix"] == "@"
        assert model["var_delim"] == "()" and model["formula_delim"] == "{}"
        assert model["commentline"] == "'"
        assert "scale_status" in model["output"]
        assert all(v.startswith("python://") for v in model["output"].values())


def test_calculator_maps_all_models():
    calc = json.loads((ROOT / ".fz" / "calculators" / "localhost_Scale.json").read_text())
    models = sorted(p.stem for p in (ROOT / ".fz" / "models").glob("*.json"))
    assert sorted(calc["models"]) == models
    assert set(calc["models"].values()) == {"bash .fz/calculators/Scale.sh"}
